{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by torn royal banners, with the glass diver adjusting his helmet while Mara studies a map and the oracle lamp flickers nearby.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "A narrow alley filled with broken statues and fallen beams, the tiny metal fox winding its tail as it picks a path.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara deciphers a warning scratched into a wall.",
      "visual_description": "Mara runs ink-stained fingers over faded carvings while the glass diver holds up a lantern, casting long shadows.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's single eye glows brighter, its flame shaping into a stern face as it speaks to the group near a broken well.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "They find the sleeping tax collector in a collapsed booth.",
      "visual_description": "A half-crushed wooden booth with papers everywhere, the tax collector snoring on a ledger with stamps stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a cracked window to open a magic door.",
      "visual_description": "The glass diver presses his helmet against a shattered pane, his body rippling as he passes through, emerging inside a dusty hall to pull a lever.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march past their hiding spot.",
      "visual_description": "The team crouches behind a collapsed cart as figures in ornate plate armor clank by, their visors hiding their faces.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox disables a tripwire near a fountain.",
      "visual_description": "A dry fountain with a rusted water spout, the tin fox carefully snipping a thin wire with its metal jaws while the others watch from a doorway.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara reads a hidden passage on her map.",
      "visual_description": "Mara unrolls a stained parchment under the oracle lamp's glow, revealing a secret route through a collapsed bell tower.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver distracts the patrols with mirror reflections.",
      "visual_description": "The glass diver positions himself on a rooftop, tilting his helmet to flash blinding light into the eyes of the armored figures below.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes and stamps a random paper.",
      "visual_description": "The tax collector stirs, yawns, and mechanically stamps a scrap of paper before falling back asleep, the noise drawing attention.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals a false wall in a chapel.",
      "visual_description": "Inside a ruined chapel with broken pews, the lamp's flame casts a silhouette that outlines a hidden seam in the stone wall.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox retrieves a key from a locked chest.",
      "visual_description": "A rusted chest under a collapsed stair, the tin fox picks the lock with a tiny wire from its tail, pulling out an iron key.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The group crosses a courtyard under falling debris.",
      "visual_description": "A wide courtyard with crumbling arches, the team sprinting as chunks of stone crash around them, the glass diver shielding the lamp.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Mara unlocks a heavy iron door with the key.",
      "visual_description": "Mara inserts the key into a massive iron door covered in rust, the lock grinding as she turns it with both hands.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver rescues a trapped figure from a mirror.",
      "visual_description": "Inside a dark chamber, the glass diver reaches into a tall cracked mirror, pulling out a dazed figure by the hand.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "They flee across a stone bridge as the city crumbles.",
      "visual_description": "A narrow bridge spanning a chasm, the team running as behind them the city towers collapse in clouds of dust.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes into the misty hills beyond.",
      "visual_description": "The bridge ends at a rocky hillside covered in fog, the team pausing to catch their breath while the oracle lamp flickers softly.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

